/* WTF Gyms branded transactional email templates.
   Each template is deliberately ONE line: Mailer::send() converts every \n in the
   body into <br> before sending, so a multi-line template renders with stray breaks.
   Table layout + inline styles because Outlook and Gmail drop <style> blocks. */
SET NAMES utf8mb4;

UPDATE email_template SET text = '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f4f5;padding:32px 12px;font-family:Arial,Helvetica,sans-serif;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" border="0" style="background:#ffffff;border:1px solid #e3e3e6;border-radius:10px;overflow:hidden;max-width:600px;"><tr><td style="background:#0f0f12;padding:20px 30px;"><span style="font:bold 22px Arial,Helvetica,sans-serif;color:#ff5a1f;letter-spacing:-1px;">WTF</span><span style="font:bold 11px Arial,Helvetica,sans-serif;color:#cfcfca;letter-spacing:2.4px;">&nbsp;&nbsp;CAREERS</span></td></tr><tr><td style="padding:34px 30px 26px 30px;"><h1 style="margin:0 0 16px;font:bold 22px Arial,Helvetica,sans-serif;color:#16161a;">Thanks for applying, %CANDFIRSTNAME%</h1><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">We have received your application and it is now with our hiring team.</p><div style="margin:22px 0;padding:16px 18px;background:#fff4ef;border-left:3px solid #ff5a1f;font-size:15px;color:#16161a;"><strong>%JBODTITLE%</strong></div><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">Every application is reviewed by a person. If your experience matches what the role needs, someone from the WTF team will contact you directly on the number and email you gave us.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">You do not need to apply again for the same role &mdash; a second application will not move you up the queue.</p></td></tr><tr><td style="background:#fafafa;border-top:1px solid #e3e3e6;padding:20px 30px;"><p style="margin:0 0 6px;font-size:12px;line-height:1.6;color:#6b6b70;">This is an automated message from the WTF Gyms careers portal. Please do not reply to this email; replies to this address are not monitored.</p><p style="margin:0;font-size:12px;color:#6b6b70;"><a href="https://careers.wtfgyms.com/careers/" style="color:#d8431a;text-decoration:none;">View all openings</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href="https://www.wtfgyms.com" style="color:#d8431a;text-decoration:none;">wtfgyms.com</a></p></td></tr></table><p style="margin:16px 0 0;font-size:11px;color:#9a9aa0;">%SITENAME%</p></td></tr></table>', allow_substitution = 1, disabled = 0 WHERE tag = 'EMAIL_TEMPLATE_CANDIDATEAPPLY';
UPDATE email_template SET text = '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f4f5;padding:32px 12px;font-family:Arial,Helvetica,sans-serif;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" border="0" style="background:#ffffff;border:1px solid #e3e3e6;border-radius:10px;overflow:hidden;max-width:600px;"><tr><td style="background:#0f0f12;padding:20px 30px;"><span style="font:bold 22px Arial,Helvetica,sans-serif;color:#ff5a1f;letter-spacing:-1px;">WTF</span><span style="font:bold 11px Arial,Helvetica,sans-serif;color:#cfcfca;letter-spacing:2.4px;">&nbsp;&nbsp;CAREERS</span></td></tr><tr><td style="padding:34px 30px 26px 30px;"><h1 style="margin:0 0 16px;font:bold 22px Arial,Helvetica,sans-serif;color:#16161a;">New application received</h1><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">Hello %JBODOWNER%, a candidate has applied through the careers portal.</p><div style="margin:22px 0;padding:16px 18px;background:#fff4ef;border-left:3px solid #ff5a1f;font-size:15px;color:#16161a;"><strong>%CANDFULLNAME%</strong><br /><span style="font-size:14px;color:#44444a;">applied for %JBODTITLE%</span></div><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;"><a href="%CANDCATSURL%" style="display:inline-block;background:#ff5a1f;color:#ffffff;font:bold 14px Arial,Helvetica,sans-serif;text-decoration:none;padding:13px 24px;border-radius:6px;">Open candidate</a></p><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">Job order: <a href="%JBODCATSURL%" style="color:#d8431a;">%JBODTITLE%</a></p></td></tr><tr><td style="background:#fafafa;border-top:1px solid #e3e3e6;padding:20px 30px;"><p style="margin:0 0 6px;font-size:12px;line-height:1.6;color:#6b6b70;">Automated notification from the WTF Gyms applicant tracking system.</p><p style="margin:0;font-size:12px;color:#6b6b70;"><a href="https://careers.wtfgyms.com/careers/" style="color:#d8431a;text-decoration:none;">View all openings</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href="https://www.wtfgyms.com" style="color:#d8431a;text-decoration:none;">wtfgyms.com</a></p></td></tr></table><p style="margin:16px 0 0;font-size:11px;color:#9a9aa0;">%SITENAME%</p></td></tr></table>', allow_substitution = 1, disabled = 0 WHERE tag = 'EMAIL_TEMPLATE_CANDIDATEPORTALNEW';
UPDATE email_template SET text = '<table width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f4f5;padding:32px 12px;font-family:Arial,Helvetica,sans-serif;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" border="0" style="background:#ffffff;border:1px solid #e3e3e6;border-radius:10px;overflow:hidden;max-width:600px;"><tr><td style="background:#0f0f12;padding:20px 30px;"><span style="font:bold 22px Arial,Helvetica,sans-serif;color:#ff5a1f;letter-spacing:-1px;">WTF</span><span style="font:bold 11px Arial,Helvetica,sans-serif;color:#cfcfca;letter-spacing:2.4px;">&nbsp;&nbsp;CAREERS</span></td></tr><tr><td style="padding:34px 30px 26px 30px;"><h1 style="margin:0 0 16px;font:bold 22px Arial,Helvetica,sans-serif;color:#16161a;">Update on your application</h1><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">Hello %CANDFULLNAME%, there is an update on your application with WTF Gyms.</p><div style="margin:22px 0;padding:16px 18px;background:#fff4ef;border-left:3px solid #ff5a1f;font-size:15px;color:#16161a;">%JBODTITLE%<br /><span style="font-size:14px;color:#44444a;">Status: <strong>%CANDSTATUS%</strong></span></div><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#44444a;">%CANDSTATUSNOTES%</p></td></tr><tr><td style="background:#fafafa;border-top:1px solid #e3e3e6;padding:20px 30px;"><p style="margin:0 0 6px;font-size:12px;line-height:1.6;color:#6b6b70;">This is an automated message from the WTF Gyms careers portal. Please do not reply to this email.</p><p style="margin:0;font-size:12px;color:#6b6b70;"><a href="https://careers.wtfgyms.com/careers/" style="color:#d8431a;text-decoration:none;">View all openings</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href="https://www.wtfgyms.com" style="color:#d8431a;text-decoration:none;">wtfgyms.com</a></p></td></tr></table><p style="margin:16px 0 0;font-size:11px;color:#9a9aa0;">%SITENAME%</p></td></tr></table>', allow_substitution = 1, disabled = 0 WHERE tag = 'EMAIL_TEMPLATE_STATUSCHANGE';

SELECT tag, LENGTH(text) AS bytes, disabled FROM email_template ORDER BY email_template_id;
